Method.Implementation:
	&html<<script type="text/javascript">
		window.getpatientList = function(lastRowId, recordsPerPage,startIndex,filterJSON) {
            try {
                const htmlRows = #server(PCS.UI.Cohorts.Util.DiseaseRegistry4.GetNextBatchHTML(lastRowId, recordsPerPage,startIndex,filterJSON))#;
                return htmlRows;
            } catch (ex) {
                console.error('Error fetching patient batch:', ex);
                return '';
            }
        };

        window.updateDashboardTab = function(filterJSON1) {
            try {
                const jsonData = #server(PCS.UI.Cohorts.Util.DiseaseRegistry4.UpdateDashboardTab(filterJSON1))#;
                if (!jsonData) return false;

                const data = JSON.parse(jsonData);

                DashboardFramework.clear();
                DashboardFramework.addMetric({title:'Total Patients', value:data.TotalPatients, icon:'👥'});
                DashboardFramework.addMetric({title:'Active Programs', value:data.ActivePrograms, icon:'📋'});
                DashboardFramework.addMetric({title:'Average Age', value:data.AvgAge, icon:'🎂'});
                DashboardFramework.addMetric({title:'Gender Ratio (M:F)', value:data.GenderRatio, icon:'⚖️'});
                DashboardFramework.addMetric({title:'Top Program', value:data.TopProgram, icon:'🏆'});

                if (data.chartLabels) {
				    const labels = JSON.parse('[' + data.chartLabels.replace(/'/g, '"') + ']');
				    const values = JSON.parse('[' + data.chartValues + ']');

				    DashboardFramework.addChart({name:'Enrollment Trend (Bar)', type:'bar', labels:labels, values:values});
				    DashboardFramework.addChart({name:'Enrollment Trend (Line)', type:'line', labels:labels, values:values});
				}
                UISwap.ready();
                DashboardFramework.render();
                return true;
            } catch (ex) {
                console.error('Dashboard update error:', ex);
                return false;
            }
        };
    </script>>

Set tLimit = 3
Set tCount = 0
Set tVisibleHTML = ""
Set tHiddenHTML = ""

For i=1:1:$Length(pList, ",") {
    Set tItem = $Piece(pList, ",", i)
    Continue:tItem=""

    Set tCount = tCount + 1
    Set tMrn = $Piece(tItem, "^", 1)
    Set tAa  = $Piece(tItem, "^", 2)
    Set tBadge = "<div class='mrn-badge'><span class='mrn-val'>"_tMrn_"</span> <span class='aa-val'>["_tAa_"]</span></div>"

    If (tCount <= tLimit) {
        Set tVisibleHTML = tVisibleHTML _ tBadge
    } Else {
        Set tHiddenHTML = tHiddenHTML _ tBadge
    }
}

Set tResult = tVisibleHTML
If (tHiddenHTML '= "") {
    Set tDivId = "mrn_hidden_" _ pUniqueId
    Set tExtra = tCount - tLimit
    Set tResult = tResult _ "<div id='"_tDivId_"' class='hidden'>" _ tHiddenHTML _ "</div>"
    Set tResult = tResult _ "<span class='mrn-toggle' onclick=""toggleMrn('"_tDivId_"', this)"">+ "_tExtra_" more</span>"
}
Quit tResult

Set tProgramId = $G(pFilters("ProgramId"))
Set tMPIID = $G(pFilters("MPIID"))
Set tMRN = $G(pFilters("MRN"))
Set tAssigningAuthority = $G(pFilters("AssigningAuthority"))
Set tFromTime = $G(pFilters("FromTime"))

If (tFromTime=""){
	Set tWhere = "WHERE (pp.ToTime IS NULL OR pp.ToTime >= CURRENT_TIMESTAMP)"
}
Set tParams = 0

If tProgramId '= "" {
    Set tWhere = tWhere _ " AND pp.Program = ?"
    Set tParams = tParams + 1
    Set tParamValues(tParams) = tProgramId
}

If tMPIID '= "" {
    Set tWhere = tWhere _ " AND pp.Patient->MPIID = ?"
    Set tParams = tParams + 1
    Set tParamValues(tParams) = tMPIID
}

If (tMRN '= "") || (tAssigningAuthority '= "") {
    Set tWhere = tWhere _ " AND EXISTS (SELECT 1 FROM HSAA.PatientNumber pnf WHERE pnf.Patient = pp.Patient AND pnf.NumberType = 'MRN'"

    If tMRN '= "" {
        Set tWhere = tWhere _ " AND pnf.Number = ?"
        Set tParams = tParams + 1
        Set tParamValues(tParams) = tMRN
    }

    If tAssigningAuthority '= "" {
        Set tWhere = tWhere _ " AND pnf.ISOAssigningAuthority = ?"
        Set tParams = tParams + 1
        Set tParamValues(tParams) = tAssigningAuthority
    }

    Set tWhere = tWhere _ ")"
}

If tFromTime '= "" {
    Set tWhere = tWhere _ " AND pp.FromTime = ?"
    Set tParams = tParams + 1
    Set tParamValues(tParams) = tFromTime
}

If pLastRef '= "" {
    Set tWhere = tWhere _ " AND pp.id < '"_pLastRef_"'"
}

Set tSql = "SELECT top("_pLimit_") "_
			"pp.id as RowId, "_
           "pp.Patient As PatientId, "_
           "pp.Patient->MPIID As MPIID, "_
           "pp.Patient->HSAAID As HSAAID, "_
           "pp.Patient->Name_FamilyName || ' ' || pp.Patient->Name_GivenName As PatientName, "_
           "pp.Patient->BirthDate As DOB, "_
           "pp.Patient->gender_code As Gender, "_
           "pp.FromTime As FromTime, "_
           "LIST(pn.Number || '^' || pn.ISOAssigningAuthority) As MRNAAList "_
           "FROM HSAA.PatientProgram pp "_
           "LEFT JOIN HSAA.PatientNumber pn ON pn.Patient = pp.Patient AND pn.NumberType = 'MRN' "_
           tWhere _ " "_
			"GROUP BY pp.id, pp.Patient, pp.FromTime, pp.Program "_
			"ORDER BY pp.id DESC"

Set tStmt = ##class(%SQL.Statement).%New()
Do tStmt.%Prepare(tSql)
Set tds=$ZDT($H)
Set ^ZSQLPat($UserName,tds)=tSql
M ^ZSQLPat($UserName,tds)=tParamValues
If tParams = 0 {
    Quit tStmt.%Execute()
} ElseIf tParams = 1 {
    Quit tStmt.%Execute(tParamValues(1))
} ElseIf tParams = 2 {
    Quit tStmt.%Execute(tParamValues(1), tParamValues(2))
} ElseIf tParams = 3 {
    Quit tStmt.%Execute(tParamValues(1), tParamValues(2), tParamValues(3))
} ElseIf tParams = 4 {
    Quit tStmt.%Execute(tParamValues(1), tParamValues(2), tParamValues(3), tParamValues(4))
} ElseIf tParams = 5 {
    Quit tStmt.%Execute(tParamValues(1), tParamValues(2), tParamValues(3), tParamValues(4), tParamValues(5))
} Else {
    Quit tStmt.%Execute(tParamValues(1), tParamValues(2), tParamValues(3), tParamValues(4), tParamValues(5), tParamValues(6))
}

Set tLimit = 3
Set tCount = 0
Set tVisibleHTML = ""
Set tHiddenHTML = ""

For i=1:1:$Length(pList, ",") {
    Set tItem = $Piece(pList, ",", i)
    Continue:tItem=""

    Set tCount = tCount + 1
    Set tMrn = $Piece(tItem, "^", 1)
    Set tAa  = $Piece(tItem, "^", 2)
    Set tBadge = "<div class='mrn-badge'><span class='mrn-val'>"_tMrn_"</span> <span class='aa-val'>["_tAa_"]</span></div>"

    If (tCount <= tLimit) {
        Set tVisibleHTML = tVisibleHTML _ tBadge
    } Else {
        Set tHiddenHTML = tHiddenHTML _ tBadge
    }
}

Set tResult = tVisibleHTML
If (tHiddenHTML '= "") {
    Set tDivId = "mrn_hidden_" _ pUniqueId
    Set tExtra = tCount - tLimit
    Set tResult = tResult _ "<div id='"_tDivId_"' class='hidden'>" _ tHiddenHTML _ "</div>"
    Set tResult = tResult _ "<span class='mrn-toggle' onclick=""toggleMrn('"_tDivId_"', this)"">+ "_tExtra_" more</span>"
}
Quit tResult

Set tHTML = ""
Set tLastRowId = ""

Try {
    // Parse JSON filters
    Set tFiltersObj = ##class(%DynamicObject).%FromJSON(pFilterJSON)

    Set tFilters("ProgramId") = tFiltersObj.ProgramId
    Set tFilters("MPIID") = tFiltersObj.MPIID
    Set tFilters("FromTime") = tFiltersObj.FromTime
    Set tFilters("MRN") = tFiltersObj.MRN
    Set tFilters("AssigningAuthority") = tFiltersObj.AssigningAuthority

    Set tResultSet = ..GetPatientList(.tFilters, pLastRowId, pLimit)

    Set tDisplayIndex = pStartIndex

    While (tResultSet.%Next()) {
        Set tPatId = tResultSet.%Get("PatientId")
      	Set tLastRowId=tResultSet.%Get("RowId")
        Set tRowMpi = tResultSet.%Get("MPIID")
        Set tHSAAID = tResultSet.%Get("HSAAID")
        Set tPatientName = $ZCVT(tResultSet.%Get("PatientName"),"O","HTML")
        Set tDOB = $ZDT($ZCVT(tResultSet.%Get("DOB"),"O","HTML"),5)

        // Gender badge
        Set tGenderRaw = $ZCVT(tResultSet.%Get("Gender"),"O","HTML")
        If (tGenderRaw = "M") {
            Set tGender = "<span class='gender-badge male'>M</span>"
        } ElseIf (tGenderRaw = "F") {
            Set tGender = "<span class='gender-badge female'>F</span>"
        } Else {
            Set tGender = "<span class='gender-badge' style='background:#f1f5f9;color:#64748b;border:1px solid #e2e8f0;'>"_tGenderRaw_"</span>"
        }

        Set tFromTime = $ZCVT(tResultSet.%Get("FromTime"),"O","HTML")

        Set tMrnDisplay = ..FormatMRNList(tResultSet.%Get("MRNAAList"), tRowMpi)

        // Build row
        Set tHTML = tHTML _ "<tr data-sno='"_tDisplayIndex_"'>"
        Set tHTML = tHTML _ "<td>"_tDisplayIndex_"</td>"
        Set tHTML = tHTML _ "<td><strong>"_tPatientName_"</strong></td>"
        Set tHTML = tHTML _ "<td>"_tDOB_"</td>"
        Set tHTML = tHTML _ "<td>"_tGender_"</td>"
        Set tHTML = tHTML _ "<td>"_tRowMpi_"</td>"
        Set tHTML = tHTML _ "<td><div class='mrn-list'>"_tMrnDisplay_"</div></td>"
        Set tHTML = tHTML _ "<td><span class='text-muted'>"_tFromTime_"</span></td>"
        Set tHTML = tHTML _ "<td align='center'><button type='button' class='btn-view' onclick='openViewer("""_tHSAAID_""")'>View</button></td>"
        Set tHTML = tHTML _ "</tr>"

        Set tDisplayIndex = tDisplayIndex + 1
    }

    // Add hidden field with last DB row ID
    If (tLastRowId '= "") {
        Set tHTML = tHTML _ "<input type='hidden' id='lastRowId' value='"_tLastRowId_"'>"
    }

    Set ^ZSQLPat=tLastRowId
} Catch (ex) {
    Set tHTML = "<tr><td colspan='8' style='color:red;text-align:center;'>Error: "_$ZCVT(ex.DisplayString(),"O","HTML")_"</td></tr>"
}

Quit tHTML

Kill pMetrics
Set tStatus = $System.Status.OK()


Try {
    Set tRS = ..ExecuteMetricsQuery(.pFilters)
    Do ..AggregateMetrics(tRS, .pFilters, .pMetrics)

} Catch (Ex) {
    Set tStatus = Ex.AsStatus()
}

Quit tStatus

Kill pTrendData
Set tStatus = $System.Status.OK()

Try {
    Set tHasFilters = $Get(%session.Data("HasFilter"))
    //If 'tHasFilters Quit

    Set tRS = ..ExecuteTrendQuery(.pFilters)

    While tRS.%Next() {
        Set tDaysSince = tRS.DaysSinceEnrollment
        If tDaysSince '= "" {
            Set pTrendData(tDaysSince) = $G(pTrendData(tDaysSince)) + 1
        }
    }
} Catch (Ex) {
    Set tStatus = Ex.AsStatus()
}

Quit tStatus

Set tParams="",tParamCount=0,tWhere="" If ($Data(pFilters)) { Set tWhere = ..BuildWhereClause(.pFilters, .tParams, .tParamCount, .pHasFilters) }
Set tSql = "SELECT COUNT(DISTINCT pp.Patient) AS TotalPatients,"_ "COALESCE(COUNT(DISTINCT pp.Program),0) AS ActivePrograms,"_ "COALESCE(SUM(CASE WHEN pp.Patient->gender_code = 'M' THEN 1 ELSE 0 END),0) AS MalePatients, "_ "COALESCE(SUM(CASE WHEN pp.Patient->gender_code = 'F' THEN 1 ELSE 0 END),0) AS FemalePatients,"_ "COALESCE(COUNT(DISTINCT pp.Patient),0) As TotalPatients,"_ "COALESCE(AVG(DATEDIFF(year, pp.Patient->BirthDate, CURRENT_DATE)),0) AS AvgAge "_ "FROM HSAA.PatientProgram pp " _ tWhere
Set ^DRP("SQL")=tSql Set tStmt = ##class(%SQL.Statement).%New() $$$ThrowOnError(tStmt.%Prepare(tSql))
Set ^DRP("Params")=tParams Set tRS = ..ExecuteDynamic(tStmt, .tParams, tParamCount) If (tRS.%SQLCODE < 0) { Throw ##class(%Exception.SQL).CreateFromSQLCODE(tRS.%SQLCODE, tRS.%Message) }
Quit tRS

Set tWhere = "WHERE (pp.ToTime IS NULL OR pp.ToTime >= CURRENT_TIMESTAMP)"
Set pParamCount = 0
Set pHasFilters = 0

If $G(pFilters("ProgramId")) '= "" {
    Set tWhere = tWhere _ " AND pp.Program = ?"
    Set pParamCount = pParamCount + 1
    Set pParams(pParamCount) = pFilters("ProgramId")
    Set pHasFilters = 1
}

If $G(pFilters("MPIID")) '= "" {
    Set tWhere = tWhere _ " AND pp.Patient->MPIID = ?"
    Set pParamCount = pParamCount + 1
    Set pParams(pParamCount) = pFilters("MPIID")
    Set pHasFilters = 1
}

If ($G(pFilters("MRN")) '= "") || ($G(pFilters("AssigningAuthority")) '= "") {
    Set tWhere = tWhere _ " AND EXISTS (SELECT 1 FROM HSAA.PatientNumber pn WHERE pn.Patient = pp.Patient AND pn.NumberType = 'MRN'"

    If $G(pFilters("MRN")) '= "" {
        Set tWhere = tWhere _ " AND pn.Number = ?"
        Set pParamCount = pParamCount + 1
        Set pParams(pParamCount) = pFilters("MRN")
    }

    If $G(pFilters("AssigningAuthority")) '= "" {
        Set tWhere = tWhere _ " AND pn.ISOAssigningAuthority = ?"
        Set pParamCount = pParamCount + 1
        Set pParams(pParamCount) = pFilters("AssigningAuthority")
    }

    Set tWhere = tWhere _ ")"
    Set pHasFilters = 1
}

If $G(pFilters("FromTime")) '= "" {
    Set tWhere = tWhere _ " AND pp.FromTime >= ?"
    Set pParamCount = pParamCount + 1
    Set pParams(pParamCount) = pFilters("FromTime")
    Set pHasFilters = 1
}

Quit tWhere

	Set (pMetrics("TotalPatients"),pMetrics("ActivePrograms"),pMetrics("NewThisPeriod"),pMetrics("MalePatientsCnt"),pMetrics("femaleCountCnt"),pMetrics("AvgAge"))=0
    If pRS.%Next() {
        Set pMetrics("TotalPatients") = pRS.TotalPatients
        Set pMetrics("ActivePrograms") = pRS.ActivePrograms
        Set pMetrics("MalePatientsCnt") = pRS.MalePatients
        Set pMetrics("femaleCountCnt") = pRS.FemalePatients
        Set pMetrics("AvgAge") = pRS.AvgAge
        Set pMetrics("GenderRatio")="NA"
        If ((pMetrics("MalePatientsCnt")'=0) && (pMetrics("femaleCountCnt")'=0)){
        	Set pMetrics("GenderRatio")=$FN((pMetrics("MalePatientsCnt")/pMetrics("femaleCountCnt")), ",", 2) _ ":1"
        }

    }
